using System.Security.Claims;using AiGateway.Api.Contracts;using AiGateway.Api.Filters;using AiGateway.Application;using AiGateway.Domain;
namespace AiGateway.Api.Controllers;
public static class ChatEndpoints
{public static IEndpointRouteBuilder MapAiChat(this IEndpointRouteBuilder endpoints){endpoints.MapPost("/api/ai/chat",HandleAsync).RequireAuthorization().AddEndpointFilter<RequestValidationFilter<ChatRequestContract>>().WithName("AiChat");return endpoints;}private static async Task<IResult> HandleAsync(ChatRequestContract contract,HttpContext context,IAiOrchestrator orchestrator,CancellationToken cancellationToken){var company=context.User.FindFirstValue("company_id")!;var user=context.User.FindFirstValue(ClaimTypes.NameIdentifier)!;if(!string.Equals(company,contract.CompanyId,StringComparison.Ordinal)||!string.Equals(user,contract.UserId,StringComparison.Ordinal))throw new AiGatewayException(ErrorCodes.AccessDenied,"A identidade informada não corresponde ao contexto autenticado.");var screen=contract.Context.ToDomain();var uc=new UserContext(company,user,context.User.FindFirstValue("erp_version")!,context.User.FindFirstValue("language")??"pt-BR",context.User.FindAll("permission").Select(x=>x.Value).ToHashSet(StringComparer.OrdinalIgnoreCase),screen);var requestId=context.Items["RequestId"]?.ToString()??Guid.CreateVersion7().ToString();var traceId=System.Diagnostics.Activity.Current?.TraceId.ToString()??context.TraceIdentifier;var response=await orchestrator.ExecuteAsync(new(contract.ConversationId,contract.Message,contract.CompanyId,contract.UserId,screen,contract.Options?.Stream??false,contract.Options?.IncludeSources??true,uc,requestId,traceId),cancellationToken);return Results.Ok(response);}}
